    try (DeferredFileOutputStream out = DeferredFileOutputStream.builder().setThreshold(threshold).setBufferSize(initialBufferSize).setPrefix(prefix).setSuffix(suffix).setDirectory(tempDirFile).setDirectory(tempDirPath.toFile()).get()) {
